package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class CpioArchiveInputStream_skip_TriageGen1Test {

    /**
     * Helper to create a dummy CPIO stream.
     * Since skip() relies on read() and ensureOpen(), we provide a controlled InputStream.
     */
    private static class MockInputStream extends InputStream {
        private final byte[] data;
        private int pos = 0;

        public MockInputStream(byte[] data) {
            this.data = data;
        }

        @Override
        public int read() throws IOException {
            if (pos >= data.length) return -1;
            return data[pos++] & 0xFF;
        }

        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            if (pos >= data.length) return -1;
            int available = data.length - pos;
            int toRead = Math.min(len, available);
            System.arraycopy(data, pos, b, off, toRead);
            pos += toRead;
            return toRead;
        }
    }

    @Test(expected = IllegalArgumentException)
    public void testSkip_NegativeN() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);
        input.skip(-1L);
    }

    @Test(expected = IOException)
    public void testSkip_NotOpen() throws IOException {
        // Assuming ensureOpen() throws IOException if the stream is closed or not initialized
        InputStream is = new ByteArrayInputStream(new byte[0]);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);
        input.close();
        input.skip(10L);
    }

    @Test
    public void testSkip_ZeroN() throws IOException {
        byte[] data = new byte[100];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        long skipped = input.skip(0L);
        Assert.assertEquals(0L, skipped);
    }

    @Test
    public void testSkip_SmallN_WithinBuffer() throws IOException {
        byte[] data = new byte[100];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // We don't know the exact tmpbuf size, but 1 is safe for testing logic
        long skipped = input.skip(5L);
        Assert.assertEquals(5L, skipped);
    }

    @Test
    public void testSkip_LargeN_ExceedingBuffer() throws IOException {
        // Create a stream that provides 50 bytes
        byte[] data = new byte[50];
        for (int i = 0; i < 50; i++) data[i] = (byte) i;

        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // Try to skip more than available
        long skipped = input.skip(100L);

        // It should return the amount actually read (50) and set entryEOF to true via the -1 check
        Assert.assertEquals(50L, skipped);
    }

    @Test
    public void testSkip_N_Equals_MaxInt() throws IOException {
        // Test the Math.min(n, Integer.MAX_VALUE) logic
        byte[] data = new byte[10];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        // Skip a value larger than Integer.MAX_VALUE
        // The logic uses max = min(n, Integer.MAX_VALUE)
        // Since data is only 10, it will hit the len == -1 case.
        long skipped = input.skip((long) Integer.MAX_VALUE + 100L);
        Assert.assertEquals(10L, skipped);
    }

    @Test
    public void testSkip_ExactBufferMultiple() throws IOException {
        // This tests the while loop where total < max
        // We use a small data set to ensure it hits the end
        byte[] data = new byte[20];
        InputStream is = new MockInputStream(data);
        CpioArchiveInputStream input = new CpioArchiveInputStream(is);

        long skipped = input.skip(20L);
        Assert.assertEquals(20L, skipped);
    }
}
